sql:
SELECT COUNT(*) AS products_still_listed
FROM products
WHERE delist_after IS NULL;

SELECT product_name, delist_after AS last_month_on_sale
FROM products
WHERE delist_after IS NOT NULL;

SELECT SUM(revenue_gbp) AS total_revenue_gbp
FROM sales
WHERE month >= (
    SELECT strftime('%Y-%m', MAX(month) || '-01', '-2 months') FROM sales
);
